sql.where:
sr.deleted = 0

    AND (sr.serial_no ILIKE '%' || #{q.keyword} || '%'
         OR s.code      ILIKE '%' || #{q.keyword} || '%'
         OR s.name      ILIKE '%' || #{q.keyword} || '%')


    AND sr.sku_id = #{q.skuId}


    AND sr.warehouse_id = #{q.warehouseId}


    AND sr.status = #{q.status}
